import { Component, Show, splitProps } from "solid-js";
import { JSX } from "solid-js/jsx-runtime";

import { Filigree, FiligreeH4Props } from "#core/ui-next/components/filigree.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

/**
 * Base props for all FiligreeTitle components.
 * - text: l10n id to render
 * - bgGlow: optionally render a subtle background glow behind the text
 * - textClass: extra classes applied to the localized text element
 */
export interface FiligreeTitleBaseProps extends JSX.HTMLAttributes<HTMLDivElement> {
	text: string;
	bgGlow?: boolean;
	textClass?: string;
	args?: LocalizedTextArgument[];
}

const BackgroundGlow: Component = () => {
	return <div class="h-24 absolute -top-7 img-fxs-header-glow pointer-events-none" />;
};

const FiligreeTitleNone: Component<FiligreeTitleBaseProps> = (props) => {
	const [local, other] = splitProps(props, ["class", "textClass", "text", "bgGlow", "args"]);

	return (
		<div
			role="heading"
			aria-level={3}
			data-name="FiligreeTitle.None"
			class={`max-w-full ${local.class ?? ""}`}
			{...other}
		>
			<Header
				class={`flex-auto max-w-full text-center justify-center ${local.textClass ?? ""}`}
				classList={{
					"text-shadow-subtle z-1": !!local.bgGlow,
				}}
			>
				<L10n.Compose
					text={local.text || ""}
					args={local.args}
				/>
			</Header>
		</div>
	);
};

const FiligreeTitleH1: Component<FiligreeTitleBaseProps> = (props) => {
	const [local, other] = splitProps(props, ["bgGlow", "textClass", "text", "class", "args"]);

	return (
		<div
			role="heading"
			aria-level={1}
			data-name="FiligreeTitle.H1"
			class={`flex flex-col items-center max-w-full relative ${local.class ?? ""}`}
			{...other}
		>
			<Show when={local.bgGlow}>
				<BackgroundGlow />
			</Show>
			<Header
				class={`flex-auto max-w-full text-center justify-center ${local.textClass ?? ""}`}
				classList={{
					"text-shadow-subtle z-1": !!local.bgGlow,
				}}
			>
				<L10n.Compose
					text={local.text || ""}
					args={local.args}
				/>
			</Header>
			<Filigree.H1 />
		</div>
	);
};

